`timescale 1ns / 1ps
//
// 8x16 bitmap font ROM, 128 code points covering 7 bit ASCII. Contents come
// from font/font.mem, generated by scripts/gen_font_rom.py from Cascadia
// Mono (SIL Open Font License). One byte per scan line, most significant
// bit is the leftmost pixel of the cell.
//
// Address is simply the character code concatenated with the row inside
// the glyph, so row 0 of code 0x41 sits at word (0x41 << 4) + 0, matching
// the order gen_font_rom.py writes the file in.
//
module font_rom (
    input  wire       clk,
    input  wire [6:0] char_code,
    input  wire [3:0] row_in_glyph,
    output reg  [7:0] row_bits
);

    reg [7:0] mem [0:2047]; // 128 glyphs x 16 rows

    initial begin
        $readmemh("font.mem", mem);
    end

    wire [10:0] addr = {char_code, row_in_glyph};

    always @(posedge clk) begin
        row_bits <= mem[addr];
    end

endmodule
